  const records=clientActivityRecords(selected);
  const projectCount=new Set(records.map(activityProjectName).filter(Boolean)).size;
  document.getElementById('detailProjectCount').textContent=`· ${projectCount} ${projectCount===1?'projeto':'projetos'}`;
